    render() { this.shadowRoot.innerHTML = `<style>:host{display:block;margin:24px auto;max-width:1000px;font-family:system-ui;color:#17212b}.card{background:#fff;border:1px solid #d9e0e7;border-radius:12px;padding:22px}.head{display:flex;justify-content:space-between;gap:12px;align-items:start}h2,h3,p{margin:0}.muted{color:#687887;font-size:13px;margin-top:5px}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;margin-top:16px}.field{display:grid;gap:5px;font-size:13px;font-weight:650}.field input,.field select{padding:9px;border:1px solid #c7d1da;border-radius:7px;font:inherit}.wide{grid-column:1/-1}.button{border:1px solid #a9cce5;background:#fff;color:#1769aa;border-radius:7px;padding:9px 12px;font:inherit;cursor:pointer}.primary{background:#1769aa;color:#fff}.row{display:flex;justify-content:space-between;gap:12px;border-top:1px solid #e5eaf0;padding:12px 0}.tag{font-size:12px;color:#566a7a}.error{color:#8f2020;background:#fff0f0;padding:9px;border-radius:7px;margin-top:12px}@media(max-width:520px){.grid{grid-template-columns:1fr}.wide{grid-column:auto}.head{display:block}.head .button{margin-top:12px}}</style><section class="card" aria-label="Empfänger- und Kanalverwaltung"><div class="head"><div><h2>Empfänger und Kanäle</h2><p class="muted">Geräte, Gruppen und verfügbare Kanäle für die Routing-Vorschau.</p></div><button class="button" data-action="new">＋ Empfänger</button></div>${this.error ? `<p class="error">${this.escape(this.error)}</p>` : ""}<div>${this.recipients.map((item) => `<div class="row"><div><strong>${this.escape(item.display_name)}</strong><div class="tag">${(item.devices || []).map((device) => `${this.escape(device.display_name)}${device.primary ? " · Primär" : ""}${device.available === false ? " · nicht verfügbar" : ""}`).join(" · ") || "Kein Gerät konfiguriert"}</div></div><span class="tag">${item.enabled ? "Aktiv" : "Deaktiviert"}</span></div>`).join("") || '<p class="muted">Noch keine Empfänger konfiguriert.</p>'}</div>${this.form || ""}</section>`; this.shadowRoot.onclick = (event) => { const action = event.target.closest("[data-action]")?.dataset.action; if (action === "new") { this.form = `<div class="grid"><label class="field"><span>Name</span><input data-field="name" placeholder="z. B. Michael" /></label><label class="field"><span>Empfänger-ID</span><input data-field="id" placeholder="michael" /></label><label class="field wide"><span>Primärgerät / Kanal</span><input data-field="device" placeholder="phone:mobile" /></label><button class="button primary" data-action="save">Speichern</button></div>`; this.render(); } if (action === "save") { const id = this.shadowRoot.querySelector('[data-field="id"]')?.value.trim(); const name = this.shadowRoot.querySelector('[data-field="name"]')?.value.trim(); const raw = this.shadowRoot.querySelector('[data-field="device"]')?.value.split(":"); if (id && name && raw?.length === 2) this.onSave?.({ recipient_id: id, display_name: name, enabled: true, devices: [{ device_id: raw[0], display_name: raw[0], channel_id: raw[1], available: true, primary: true }] }); else { this.error = "Name, ID und Gerät:Kanal sind erforderlich."; this.render(); } } }; }
    escape(value) { return String(value ?? "").replace(/[&<>"']/g, (character) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[character]); }
